{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE or REPLACE TABLE snitch_db.maplemonk.grn_issues_joined as WITH grn_base AS ( SELECT UNIQUEKEY, ORIGIN, ORDER_DATE, EDD, ORDER_NUMBER, SUPPLIER_ORDER_NO, TRANSFER_BRANCH_CODE, TO_PARTY AS ORIGINAL_BRANCH_NAME, FROM_PARTY AS VENDOR_GRN, PARTY_USER_CODE, BRANCH_SHORT_NAME, CAST(VOUCH_CODE AS VARCHAR) AS GRN_NUMBER, ORDER_PREFIX, ACTION_CODE, NET_ORDER_AMOUNT, ORDER_AMOUNT, TOTAL_TAX, AGENT_NAME, LOGIC_USER_CODE, LOT_NUMBER, PO_MRP, PENDING_QTY, TOTAL_QTY, TXN_CODE, DATE_TRUNC(\'WEEK\', ORDER_DATE)::DATE AS WEEK_START_DATE, CASE WHEN COALESCE(TOTAL_QTY,0)=COALESCE(PENDING_QTY,0) THEN \'GRN Pending\' ELSE \'GRN Done\' END AS GRN_STATUS FROM snitch_db.maplemonk.logic_purchase_order ), issue_base AS ( SELECT CREATED_AT_DATE, UPDATED_AT_DATE, EVIDENCE_WITH_HTTPS, ID AS ISSUE_ID, QTY AS ISSUE_QTY, SKU, \"Issue\" as ISSUE, VENDOR AS VENDOR_ISSUE, COMMENTS, EVIDENCE, PO_NUMBER, SUB_ISSUE, CREATED_AT AS ISSUE_CREATED_AT, CREATED_BY, INVOICE_NUMBER, LAST_UPDATED_AT AS ISSUE_LAST_UPDATED_AT FROM snitch_db.maplemonk.issues_factory_sorted ), severity_map AS ( SELECT * FROM VALUES (\'Shade variations\', 10), (\'Double barcode\', 9), (\'Shortage/Excess\', 9), (\'Size mismatch\', 9), (\'Costing issues\', 8), (\'Wrong barcode\', 7), (\'Without barcode\', 7), (\'Packing conditions not as per SOP\', 6), (\'Relevant documents not available (QC docs / CAD file / packing list etc.)\', 5), (\'Costing not matching with invoice\', 5), (\'Qty mismatch (QC report vs invoice qty)\', 5), (\'Invoice issues (size-level missing / PO number missing / SKU missing)\', 4), (\'PO issues (expired / not available / entity names mismatch)\', 3) AS severity_map(SUB_ISSUE_RAW, SEVERITY) ), severity_norm AS ( SELECT LOWER(REGEXP_REPLACE(SUB_ISSUE_RAW, \'[^a-z0-9]+\',\'\')) AS SUB_ISSUE_KEY, SEVERITY FROM severity_map ), rfid_base AS ( SELECT REGEXP_REPLACE(\"Doc No\", \'.*-\', \'\') AS GRN_MATCH_KEY, \"Matching Status\" AS MATCHING_STATUS FROM snitch_db.maplemonk.s3_rfid_inward ) SELECT g.UNIQUEKEY, g.ORIGIN, g.ORDER_DATE, g.EDD, g.ORDER_NUMBER, g.SUPPLIER_ORDER_NO, g.TRANSFER_BRANCH_CODE, CASE WHEN LOWER(i.CREATED_BY) IN (\'punit.c@snitch.com\',\'akash.s@snitch.com\') THEN \'SAPL-NORTH-TAURU\' WHEN LOWER(i.CREATED_BY) IN ( \'inward.erp.warehouse@snitch.com\', \'gopal.k@snitch.com\', \'guramma.s@snitch.com\', \'hemanth.t@snitch.com\', \'nitin.m@snitch.com\' ) THEN \'SAPL-WH2\' ELSE g.BRANCH_SHORT_NAME END AS BRANCH_SHORT_NAME, g.VENDOR_GRN, g.PARTY_USER_CODE, g.GRN_NUMBER, g.ORDER_PREFIX, g.LOT_NUMBER AS PO_NUMBER_GRN, g.NET_ORDER_AMOUNT, g.ORDER_AMOUNT, g.TOTAL_TAX, g.AGENT_NAME, g.LOGIC_USER_CODE, g.PO_MRP, g.PENDING_QTY, g.TOTAL_QTY, g.TXN_CODE, g.WEEK_START_DATE, g.GRN_STATUS, r.MATCHING_STATUS AS MATCHING_STATUS, CASE WHEN LOWER(r.MATCHING_STATUS) = \'pending\' THEN \'NON RFID\' ELSE \'RFID\' END AS RFID_STATUS, i.ISSUE_ID, i.CREATED_AT_DATE AS ISSUE_CREATED_AT_DATE, i.UPDATED_AT_DATE AS ISSUE_UPDATED_AT_DATE, i.EVIDENCE_WITH_HTTPS, i.ISSUE_QTY, i.SKU, i.Issue, i.SUB_ISSUE, i.VENDOR_ISSUE, i.COMMENTS, i.EVIDENCE, i.PO_NUMBER AS PO_NUMBER_ISSUE, i.INVOICE_NUMBER, i.ISSUE_CREATED_AT, i.CREATED_BY AS ISSUE_CREATED_BY, i.ISSUE_LAST_UPDATED_AT, COALESCE(s.SEVERITY,0) AS ISSUE_SEVERITY, CASE WHEN i.ISSUE_ID IS NULL THEN 0 ELSE 1 END AS HAS_DISCREPANCY FROM grn_base g LEFT JOIN issue_base i ON TRIM(CAST(i.PO_NUMBER AS VARCHAR)) = TRIM(CAST(g.LOT_NUMBER AS VARCHAR)) LEFT JOIN rfid_base r ON r.GRN_MATCH_KEY = g.GRN_NUMBER LEFT JOIN severity_norm s ON LOWER(REGEXP_REPLACE(i.SUB_ISSUE, \'[^a-z0-9]+\',\'\')) = s.SUB_ISSUE_KEY;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            